   if(!grandstandAudit.some(s=>Math.abs(s.x-(minX+maxX)/2)<s.length+s.rows*1.25+(maxX-minX)/2+2&&Math.abs(s.z-(minZ+maxZ)/2)<s.length+s.rows*1.25+(maxZ-minZ)/2+2))continue;
